return output;

// Today's date in YYYYMMDD format (IST)
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date()).replace(/-/g, '');

const output = [];

for (const item of items) {

  const agreementValue = Number(item.json.Agreement_Value__c) || 0;

  // Calculate difference between Site Visit Date and Booking Date
  const svDate = new Date(item.json.SV_Date__c);
  const bookingDate = new Date(item.json.Booking_Date);

  // Calculate difference in days
  const differenceInDays = Math.floor(
    (Date.UTC(
      bookingDate.getUTCFullYear(),
      bookingDate.getUTCMonth(),
      bookingDate.getUTCDate()
    ) -
    Date.UTC(
      svDate.getUTCFullYear(),
      svDate.getUTCMonth(),
      svDate.getUTCDate()
    )) / (1000 * 60 * 60 * 24)
  );

  // Skip invalid dates or bookings before Site Visit
  if (
    isNaN(svDate.getTime()) ||
    isNaN(bookingDate.getTime()) ||
    differenceInDays < 0
  ) {
    continue;
  }

  let amount = 0;

  // Agreement Value <= 5 Cr
  if (agreementValue <= 50000000) {

    if (differenceInDays <= 15) {
      amount = 100;
    } else {
      continue;
    }

  }

  // Agreement Value > 5 Cr
  else {

    if (differenceInDays <= 15) {
      amount = 100;
    } 
    else if (differenceInDays <= 30) {
      amount = 50;
    } 
    else {
      continue;
    }

  }

  const externalTransactionId =
    `RULE_12_${item.json.ID}_${today}`;

  output.push({
    json: {
      id: item.json.ID,
      customer_code: item.json.customer_id,
      customer_mobile: item.json.customer_mobile,
      customer_name: item.json.customer_name,
      amount: amount,
      remarks: "Booking within eligible Site Visit duration",
      transaction_note: "Credit points based on Agreement Value and Booking Date",
      payment_mode: "cash",
      topup_by: "automation",
      booking_date: item.json.Booking_Date,
      sv_date: item.json.SV_Date__c,
      booking_id: item.json.X18_Digit_Booking_ID__c,
      today_delta_additions: item.json.today_delta_additions,

      // Existing fields
      rule_name: "Booking Within Eligible Site Visit Duration",
      n8n_rule_id: "12",
      category: "Booking",

      // Added fields
      external_transaction_id: externalTransactionId,
      organization_id: 71,
      organization_name: "Rustomjee"
    }
  });

}

return output;


